/*
|--------------------------------------------------------------------------
| MAP ERROR BOUNDARY
|--------------------------------------------------------------------------
*/

class MapErrorBoundary extends Component {
  constructor(props) {
    super(props);

    this.state = {
      hasError: false,
    };
  }

  static getDerivedStateFromError() {
    return {
      hasError: true,
    };
  }

  componentDidCatch(error) {
    console.warn(
      'MapView render error:',
      error?.message
    );
  }

  render() {
    const {
      fallbackUrl,
      palette,
    } = this.props;

    if (this.state.hasError) {
      return (
        <View
          style={[
            styles.mapFallback,
            {
              backgroundColor: palette.surfaceTertiary,
              borderColor: palette.border,
            },
          ]}
        >
          <View
            style={[
              styles.mapFallbackIcon,
              {
                backgroundColor: palette.primaryLight,
              },
            ]}
          >
            <Ionicons
              name="map-outline"
              size={25}
              color={palette.primary}
            />
          </View>

          <Text
            style={[
              styles.mapFallbackTitle,
              {
                color: palette.text,
              },
            ]}
          >
            Map unavailable
          </Text>

          <Text
            style={[
              styles.mapFallbackText,
              {
                color: palette.textTertiary,
              },
            ]}
          >
            We couldn't load the map preview.
          </Text>

          {fallbackUrl ? (
            <Pressable
              onPress={() =>
                Linking.openURL(fallbackUrl)
              }
              style={[
                styles.mapFallbackButton,
                {
                  backgroundColor: palette.primary,
                },
              ]}
            >
              <Ionicons
                name="navigate-outline"
                size={16}
                color="#FFFFFF"
              />

              <Text style={styles.mapFallbackButtonText}>
                Open Maps
              </Text>
            </Pressable>
          ) : null}
        </View>
      );
    }

    return this.props.children;
  }
}

/*
|--------------------------------------------------------------------------
| SAFE MAP
|--------------------------------------------------------------------------
*/

function SafeMapView({
  latitude,
  longitude,
  palette,
}) {
  const lat = Number(latitude);
  const lng = Number(longitude);

  const valid =
    !isNaN(lat) &&
    !isNaN(lng) &&
    lat !== 0 &&
    lng !== 0 &&
    Math.abs(lat) <= 90 &&
    Math.abs(lng) <= 180;

  const mapsUrl =
    `https://www.google.com/maps/dir/?api=1&destination=${lat},${lng}`;

  if (!valid) {
    return (
      <View
        style={[
          styles.mapFallback,
          {
            backgroundColor: palette.surfaceTertiary,
            borderColor: palette.border,
          },
        ]}
      >
        <View
          style={[
            styles.mapFallbackIcon,
            {
              backgroundColor: palette.primaryLight,
            },
          ]}
        >
          <Ionicons
            name="location-outline"
            size={25}
            color={palette.primary}
          />
        </View>

        <Text
          style={[
            styles.mapFallbackTitle,
            {
              color: palette.text,
            },
          ]}
        >
          Location unavailable
        </Text>

        <Text
          style={[
            styles.mapFallbackText,
            {
              color: palette.textTertiary,
            },
          ]}
        >
          Location details are not available.
        </Text>
      </View>
    );
  }

  return (
    <MapErrorBoundary
      fallbackUrl={mapsUrl}
      palette={palette}
    >
      <View
        style={[
          styles.mapContainer,
          {
            borderColor: palette.border,
          },
        ]}
      >
        <MapView
          provider={PROVIDER_GOOGLE}
          style={styles.map}
          initialRegion={{
            latitude: lat,
            longitude: lng,
            latitudeDelta: 0.005,
            longitudeDelta: 0.005,
          }}
          scrollEnabled={false}
          zoomEnabled={false}
          pitchEnabled={false}
          rotateEnabled={false}
        >
          <Marker
            coordinate={{
              latitude: lat,
              longitude: lng,
            }}
            pinColor={palette.primary}
          />
        </MapView>

        <Pressable
          onPress={() =>
            Linking.openURL(mapsUrl)
          }
          style={[
            styles.mapDirectionsButton,
            {
              backgroundColor: palette.surface,
              borderColor: palette.border,
            },
          ]}
        >
          <View
            style={[
              styles.mapDirectionsIcon,
              {
                backgroundColor: palette.primaryLight,
              },
            ]}
          >
            <Ionicons
              name="navigate-outline"
              size={16}
              color={palette.primary}
            />
          </View>

          <Text
            style={[
              styles.mapDirectionsText,
              {
                color: palette.text,
              },
            ]}
          >
            Get Directions
          </Text>

          <Ionicons
            name="chevron-forward"
            size={16}
            color={palette.textTertiary}
          />
        </Pressable>
      </View>
    </MapErrorBoundary>
  );
}

/*
|--------------------------------------------------------------------------
| DESCRIPTION HELPERS
|--------------------------------------------------------------------------
*/

function parseBenefits(description = '') {
  if (!description) {
    return [];
  }

  const lines = description
    .split(/[\n•\-\*]/)
    .map(item => item.trim())
    .filter(
      item =>
        item.length > 4 &&
        item.length < 100
    );

  return lines.slice(0, 6);
}

