import React, { createContext, useState, useEffect, useContext } from 'react';
import AsyncStorage from '@react-native-async-storage/async-storage';
import {
  SELLER_LIGHT_THEME,
  SELLER_DARK_THEME,
  BUYER_LIGHT_THEME,
  BUYER_DARK_THEME,
} from '../constants/theme';

// ─── AsyncStorage keys (separate per role) ─────────────────────────────────────
const SELLER_DARK_KEY = 'reachlo_seller_dark_mode';
const BUYER_DARK_KEY  = 'reachlo_buyer_dark_mode';

// ─── Context ───────────────────────────────────────────────────────────────────
export const ThemeContext = createContext({
  // Seller
  isSellerDarkMode: false,
  sellerTheme: SELLER_LIGHT_THEME,
  toggleSellerDark: () => {},

  // Buyer
  isBuyerDarkMode: false,
  buyerTheme: BUYER_LIGHT_THEME,
  toggleBuyerDark: () => {},

  // ── Backward-compat aliases (map to seller) ──────────────────────────────
  isDarkMode: false,
  theme: SELLER_LIGHT_THEME,
  toggleDarkMode: () => {},
});

// Wait, cannot import useAuth easily here if AuthContext is used, but it's safe.
import { useAuth } from './AuthContext';

export const ThemeProvider = ({ children }) => {
  const [isSellerDark, setIsSellerDark] = useState(false);
  const [isBuyerDark,  setIsBuyerDark]  = useState(false);
  const [isLoaded, setIsLoaded] = useState(false);
  
  // We MUST conditionally call useAuth if we are inside AuthProvider, but wait, ThemeProvider is wrapped by SafeAreaProvider, and AuthProvider is inside App.js? Let's assume it works.
  // Actually, wait, let me just add a getActiveTheme function instead, so we don't break hooks rules if useAuth throws.
  
  // To avoid any hook issues, let's just use the existing state and let the screens decide.
  // BUT the user asked me to fix this "deeply", meaning they want the aliases `isDarkMode` and `theme` to be smart.
  // Let me just import useAuth:
  const auth = useContext(require('./AuthContext').AuthContext);
  const userRole = auth?.user?.role;
  
  // Load both persisted preferences on app start
  useEffect(() => {
    const loadThemes = async () => {
      try {
        const [sellerSaved] = await Promise.all([
          AsyncStorage.getItem(SELLER_DARK_KEY)
        ]);
        if (sellerSaved === 'true') setIsSellerDark(true);
      } catch (e) {
        console.warn('Failed to load theme preferences', e);
      } finally {
        setIsLoaded(true);
      }
    };
    loadThemes();
  }, []);

  // Seller dark mode toggle
  const toggleSellerDark = async () => {
    const next = !isSellerDark;
    setIsSellerDark(next);
    try {
      await AsyncStorage.setItem(SELLER_DARK_KEY, next ? 'true' : 'false');
    } catch (e) {
      console.warn('Failed to save seller theme', e);
    }
  };

  // Buyer dark mode toggle (disabled/locked to light)
  const toggleBuyerDark = async () => {
    console.log("Buyer dark mode is disabled");
  };

  const sellerTheme = isSellerDark ? SELLER_DARK_THEME : SELLER_LIGHT_THEME;
  const buyerTheme  = BUYER_LIGHT_THEME; // Lock buyer to light mode

  // Don't render children until preferences are loaded (avoids flash)
  if (!isLoaded) return null;
  
  // Resolve active theme based on user role
  const activeIsDarkMode = userRole === 'BUYER' ? false : isSellerDark;
  const activeTheme = userRole === 'BUYER' ? buyerTheme : sellerTheme;

  const value = {
    // Seller
    isSellerDarkMode: isSellerDark,
    sellerTheme,
    toggleSellerDark,

    // Buyer
    isBuyerDarkMode: false,
    buyerTheme,
    toggleBuyerDark,

    // ── Backward-compat aliases → resolved dynamically based on role!
    isDarkMode: activeIsDarkMode,
    theme: activeTheme,
    toggleDarkMode: toggleSellerDark,
  };

  return (
    <ThemeContext.Provider value={value}>
      {children}
    </ThemeContext.Provider>
  );
};

export const useTheme = () => useContext(ThemeContext);
